//! Document attributes (the `:name: value` header entries, plus built-ins).

use std::borrow::Cow;
use std::collections::BTreeMap;

/// Semantic formatting generated by substitutions, independent of a backend.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AttributeFormat {
    Strong,
    Emphasis,
    Monospace,
    Mark,
    Superscript,
    Subscript,
    /// Unquoted text carrying an id or role (also wraps typographic quotes).
    Span,
}

impl AttributeFormat {
    pub fn name(self) -> &'static str {
        match self {
            Self::Strong => "strong",
            Self::Emphasis => "emphasis",
            Self::Monospace => "monospace",
            Self::Mark => "mark",
            Self::Superscript => "superscript",
            Self::Subscript => "subscript",
            Self::Span => "span",
        }
    }
}

/// Semantic link properties generated by substitutions. Backends choose markup.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct AttributeLink {
    /// Fields retain substituted lexical spelling, including entity protection.
    pub target: String,
    pub id: Option<String>,
    pub role: Option<String>,
    pub title: Option<String>,
    pub window: Option<String>,
    pub rel: Option<String>,
}

/// A cross-reference resolved like Ruby's `InlineXrefMacroRx` (the attributes
/// it gives its `:xref` anchor node). In [`AttributePart::OpenXref`] the
/// fields keep their lexical entity protection, like link fields; in
/// [`Inline::CrossReference`](crate::Inline::CrossReference) they are decoded.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Xref {
    /// The link target (Ruby's `node.target`): `#id`, `doc.html#id`,
    /// `doc.html`, or `#` for the current document.
    pub target: String,
    /// The id whose reftext or title labels a textless reference; `path#id`
    /// or `path` for another document; `None` for the current document
    /// (`xref:doc.adoc[]` naming this document or an included one).
    pub refid: Option<String>,
    /// Another document's output path, with `relfileprefix` and
    /// `relfilesuffix` (default `outfilesuffix`) applied. A textless
    /// interdocument reference displays it.
    pub path: Option<String>,
    /// The id within the target document, if any.
    pub fragment: Option<String>,
    /// The lexical refid of a bare id outside compat mode whose lookup is
    /// pending: when the id is unknown, Ruby looks this spelling (with any
    /// generated tags) up as a title or reftext (a *natural*
    /// cross-reference). Taken once resolution has looked it up.
    pub(crate) natural: Option<String>,
    /// `role` from the macro's attribute list.
    pub role: Option<String>,
    /// Link constraints of an interdocument reference (`window`, `opts`).
    pub window: Option<String>,
    pub rel: Option<String>,
    /// `xrefstyle` from the macro's attribute list; otherwise the document
    /// attribute at the reference applies.
    pub xrefstyle: Option<String>,
}

impl Xref {
    /// An internal reference to `id` (`#id`).
    pub fn to_id(id: impl Into<String>) -> Self {
        let id = id.into();
        Self {
            target: format!("#{id}"),
            refid: Some(id.clone()),
            fragment: Some(id),
            ..Default::default()
        }
    }

    /// Apply `f` to every text field (e.g. decoding entity protection).
    pub(crate) fn map_fields(&mut self, mut f: impl FnMut(&str) -> String) {
        self.target = f(&self.target);
        for value in [
            &mut self.refid,
            &mut self.path,
            &mut self.fragment,
            &mut self.role,
            &mut self.window,
            &mut self.rel,
            &mut self.xrefstyle,
        ]
        .into_iter()
        .flatten()
        {
            *value = f(value);
        }
    }
}

/// Text and semantic boundaries generated by attribute substitutions.
#[derive(Debug, Clone, PartialEq)]
pub enum AttributePart {
    Text(String),
    Raw(String),
    /// Boundaries stay separate because ordered substitutions may produce
    /// overlapping formatting. They do not contribute to the flat text API.
    Open(AttributeFormat),
    /// Values retain the reference's substituted lexical spelling, including
    /// entity protection. `role` preserves significant whitespace and emptiness.
    OpenWithAttributes {
        format: AttributeFormat,
        id: Option<String>,
        role: Option<String>,
    },
    Close(AttributeFormat),
    OpenLink(AttributeLink),
    CloseLink,
    /// A semantic hard line break generated by post replacements.
    LineBreak,
    /// An inline anchor recognized by the macros stage (Ruby's
    /// `InlineAnchorRx`). Its reftext is registry metadata, not content.
    Anchor(String),
    /// A cross-reference recognized by the macros stage (Ruby's
    /// `InlineXrefMacroRx`). Its fields retain the lexical entity protection
    /// like link fields. A pair with no label between receives the target's
    /// label during conversion.
    OpenXref(Xref),
    CloseXref,
}

impl AttributePart {
    /// Text content; formatting boundaries contribute an empty string.
    pub fn text(&self) -> &str {
        match self {
            Self::Text(text) | Self::Raw(text) => text,
            Self::Open(_)
            | Self::OpenWithAttributes { .. }
            | Self::Close(_)
            | Self::OpenLink(_)
            | Self::CloseLink
            | Self::LineBreak
            | Self::Anchor(_)
            | Self::OpenXref(_)
            | Self::CloseXref => "",
        }
    }

    pub fn is_raw(&self) -> bool {
        matches!(self, Self::Raw(_))
    }

    pub(crate) fn is_special(&self) -> bool {
        !matches!(self, Self::Text(_))
    }

    pub(crate) fn is_boundary(&self) -> bool {
        matches!(
            self,
            Self::Open(_)
                | Self::OpenWithAttributes { .. }
                | Self::Close(_)
                | Self::OpenLink(_)
                | Self::CloseLink
                | Self::LineBreak
                | Self::Anchor(_)
                | Self::OpenXref(_)
                | Self::CloseXref
        )
    }

    pub(crate) fn map_metadata(mut self, mut f: impl FnMut(&str) -> String) -> Self {
        match &mut self {
            Self::OpenWithAttributes { id, role, .. } => {
                for value in [id, role].into_iter().flatten() {
                    *value = f(value);
                }
            }
            Self::Anchor(id) => *id = f(id),
            Self::OpenXref(xref) => xref.map_fields(f),
            Self::OpenLink(link) => {
                link.target = f(&link.target);
                for value in [
                    &mut link.id,
                    &mut link.role,
                    &mut link.title,
                    &mut link.window,
                    &mut link.rel,
                ]
                .into_iter()
                .flatten()
                {
                    *value = f(value);
                }
            }
            _ => {}
        }
        self
    }

    pub(crate) fn with_lexical_attributes(&self, text: &str) -> Option<Self> {
        if let Self::OpenLink(link) = self {
            let mut body = text.strip_prefix("<a")?.strip_suffix('>')?;
            let mut updated = link.clone();
            for (key, field) in [
                ("rel", &mut updated.rel),
                ("target", &mut updated.window),
                ("title", &mut updated.title),
                ("class", &mut updated.role),
                ("id", &mut updated.id),
            ] {
                if field.is_some() {
                    let (rest, value) = body.rsplit_once(&format!(" {key}=\""))?;
                    *field = Some(value.strip_suffix('"')?.to_owned());
                    body = rest;
                }
            }
            updated.target = body.strip_prefix(" href=\"")?.strip_suffix('"')?.to_owned();
            return Some(Self::OpenLink(updated));
        }
        let Self::OpenWithAttributes { format, id, role } = self else {
            return None;
        };
        let prefix = Self::Open(*format).lexical().into_owned();
        let mut body = text
            .strip_prefix(prefix.trim_end_matches('>'))?
            .strip_suffix('>')?;
        let new_role = if role.is_some() {
            let (rest, value) = body.rsplit_once(" class=\"")?;
            body = rest;
            Some(value.strip_suffix('"')?.to_owned())
        } else {
            None
        };
        let new_id = if id.is_some() {
            let value = body.strip_prefix(" id=\"")?.strip_suffix('"')?;
            body = "";
            Some(value.to_owned())
        } else {
            None
        };
        if !body.is_empty() {
            return None;
        }
        Some(Self::OpenWithAttributes {
            format: *format,
            id: new_id,
            role: new_role,
        })
    }

    /// A temporary reference spelling for ordered stages, never the stored
    /// value. Backends render the semantic boundaries themselves.
    pub(crate) fn lexical(&self) -> Cow<'_, str> {
        use AttributeFormat::*;
        Cow::Borrowed(match self {
            Self::OpenLink(link) => {
                let mut text = format!("<a href=\"{}\"", link.target);
                for (key, value) in [
                    ("id", &link.id),
                    ("class", &link.role),
                    ("title", &link.title),
                    ("target", &link.window),
                    ("rel", &link.rel),
                ] {
                    if let Some(value) = value {
                        text.push_str(&format!(" {key}=\"{value}\""));
                    }
                }
                text.push('>');
                return Cow::Owned(text);
            }
            Self::CloseLink | Self::CloseXref => "</a>",
            Self::OpenXref(xref) => {
                let mut text = format!("<a href=\"{}\"", xref.target);
                for (key, value) in [
                    ("class", &xref.role),
                    ("target", &xref.window),
                    ("rel", &xref.rel),
                ] {
                    if let Some(value) = value {
                        text.push_str(&format!(" {key}=\"{value}\""));
                    }
                }
                text.push('>');
                return Cow::Owned(text);
            }
            Self::LineBreak => "<br>",
            Self::Anchor(id) => return Cow::Owned(format!("<a id=\"{id}\"></a>")),
            Self::OpenWithAttributes { format, id, role } => {
                let mut text = Self::Open(*format).lexical().into_owned();
                text.pop();
                if let Some(id) = id {
                    text.push_str(&format!(" id=\"{id}\""));
                }
                if let Some(role) = role {
                    text.push_str(&format!(" class=\"{role}\""));
                }
                text.push('>');
                return Cow::Owned(text);
            }
            Self::Open(Strong) => "<strong>",
            Self::Close(Strong) => "</strong>",
            Self::Open(Emphasis) => "<em>",
            Self::Close(Emphasis) => "</em>",
            Self::Open(Monospace) => "<code>",
            Self::Close(Monospace) => "</code>",
            Self::Open(Mark) => "<mark>",
            Self::Close(Mark) => "</mark>",
            Self::Open(Superscript) => "<sup>",
            Self::Close(Superscript) => "</sup>",
            Self::Open(Subscript) => "<sub>",
            Self::Close(Subscript) => "</sub>",
            Self::Open(Span) => "<span>",
            Self::Close(Span) => "</span>",
            _ => self.text(),
        })
    }
}

pub(crate) fn push_value(parts: &mut Vec<AttributePart>, part: AttributePart) {
    match part {
        part if part.is_boundary() => parts.push(part),
        _ => push_part(parts, part.text(), part.is_raw()),
    }
}

pub(crate) fn push_part(parts: &mut Vec<AttributePart>, text: &str, raw: bool) {
    if text.is_empty() {
        return;
    }
    match parts.last_mut() {
        Some(AttributePart::Raw(last)) if raw => last.push_str(text),
        Some(AttributePart::Text(last)) if !raw => last.push_str(text),
        _ => parts.push(if raw {
            AttributePart::Raw(text.to_owned())
        } else {
            AttributePart::Text(text.to_owned())
        }),
    }
}

pub fn parts_text(parts: &[AttributePart]) -> String {
    parts.iter().map(AttributePart::text).collect()
}

/// Remove the special-character protection of a lexical metadata value.
pub(crate) fn decode_special(lexical: &str) -> String {
    lexical
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
}

/// Ordered map of document attributes. `BTreeMap` keeps output deterministic,
/// which matters for snapshot/TCK testing.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Attributes {
    // Transient block substitution context, never part of document snapshots
    // or the named attribute table. A local option affects p (also in selected
    // pass stages), but cannot resolve {hardbreaks-option} in the a stage.
    pub(crate) local_hardbreaks: bool,
    map: BTreeMap<String, String>,
    parts: BTreeMap<String, Vec<AttributePart>>,
}

impl Attributes {
    pub(crate) fn hardbreaks(&self) -> bool {
        self.local_hardbreaks || self.get("hardbreaks-option").is_some()
    }

    pub fn new() -> Self {
        Self::default()
    }

    pub fn set(&mut self, key: impl Into<String>, value: impl Into<String>) {
        let key = key.into().to_lowercase();
        self.parts.remove(&key);
        self.map.insert(key, value.into());
    }

    /// Preserve literal/raw parts and formatting through attribute substitutions.
    pub fn set_parts(&mut self, key: impl Into<String>, parts: Vec<AttributePart>) {
        let key = key.into().to_lowercase();
        let mut merged = Vec::new();
        for part in parts {
            push_value(&mut merged, part);
        }
        self.set(&key, parts_text(&merged));
        if merged.iter().any(AttributePart::is_special) {
            self.parts.insert(key, merged);
        }
    }

    /// Raw/formatting boundaries; absent means the entire value is literal text.
    pub fn raw_parts(&self, key: &str) -> Option<&[AttributePart]> {
        self.raw_parts_exact(&key.to_lowercase())
    }

    // Serialization follows exact iter keys, including case-sensitive counters.
    pub(crate) fn raw_parts_exact(&self, key: &str) -> Option<&[AttributePart]> {
        self.parts.get(key).map(Vec::as_slice)
    }

    pub(crate) fn value_parts(&self, key: &str) -> Option<Vec<AttributePart>> {
        self.get(key).map(|text| {
            self.raw_parts(key)
                .map_or_else(|| vec![AttributePart::Text(text.to_owned())], <[_]>::to_vec)
        })
    }

    // Counter names deliberately bypass ordinary case folding (Ruby's counter
    // registry uses the supplied name verbatim).
    pub(crate) fn counter_value(&self, key: &str) -> Option<String> {
        self.map.get(key).map(|v| {
            self.parts
                .get(key)
                .map_or_else(|| v.clone(), |p| reference_text(p))
        })
    }
    pub(crate) fn set_counter(&mut self, key: &str, value: &str) {
        self.parts
            .insert(key.into(), vec![AttributePart::Raw(value.into())]);
        self.map.insert(key.into(), value.into());
    }

    pub fn get(&self, key: &str) -> Option<&str> {
        self.map.get(&key.to_lowercase()).map(String::as_str)
    }

    pub fn remove(&mut self, key: &str) -> Option<String> {
        self.parts.remove(&key.to_lowercase());
        self.map.remove(&key.to_lowercase())
    }

    pub fn iter(&self) -> impl Iterator<Item = (&str, &str)> {
        self.map.iter().map(|(k, v)| (k.as_str(), v.as_str()))
    }

    pub fn is_empty(&self) -> bool {
        self.map.is_empty()
    }
}

/// The reference compares the protected attribute to unprotected declarations.
/// This temporary lexical view is not stored in the AST or rendered by core.
pub(crate) fn reference_text(parts: &[AttributePart]) -> String {
    let mut result = String::new();
    for part in parts {
        for ch in part.lexical().chars() {
            if part.is_special() {
                result.push(ch);
            } else {
                result.push_str(match ch {
                    '<' => "&lt;",
                    '>' => "&gt;",
                    '&' => "&amp;",
                    _ => {
                        result.push(ch);
                        continue;
                    }
                });
            }
        }
    }
    result
}
